import path from 'node:path';
import fs from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const DATA_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Path of the file relative to the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error(`Unknown tool: ${name}`);
  }
  const { path: relPath } = args;
  if (typeof relPath !== 'string' || relPath.length === 0) {
    throw new Error('path is required and must be a non-empty string');
  }
  const absPath = path.resolve(DATA_DIR, relPath);
  if (absPath !== DATA_DIR && !absPath.startsWith(DATA_DIR + path.sep)) {
    throw new Error('Path traversal is not allowed');
  }
  let stat;
  try {
    stat = await fs.stat(absPath);
  } catch (e) {
    throw new Error(`File not found: ${relPath}`);
  }
  if (!stat.isFile()) {
    throw new Error(`Not a file: ${relPath}`);
  }
  const ext = path.extname(absPath).toLowerCase();
  const text = `path: ${relPath}\nsize: ${stat.size} bytes\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }]
  };
}
